const cfg = $input.first()?.json || {};
if (!cfg.apiKey) throw new Error('Config missing apiKey');
if (!cfg.locationId) throw new Error('Config missing locationId');

const workflowName = String(cfg.workflowName || 'LT - GHL Daily Calls Ingest').trim();
const apiBaseUrl = String(cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const apiKey = String(cfg.apiKey || '').trim();
const locationId = String(cfg.locationId || '').trim();
const batchSize = Number(cfg.batchSize || 100);
const sourceSystem = String(cfg.sourceSystem || 'ghl');

const headers = {
  Authorization: 'Bearer ' + apiKey,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

const batchId = 'lt-calls-' + new Date().toISOString().replace(/[:.]/g, '-');
const requestUrl = apiBaseUrl + '/conversations/search';
const requestBody = {
  locationId: locationId,
  type: 'TYPE_CALL',
  limit: batchSize,
};

async function requestJson(url, body) {
  try {
    return await this.helpers.httpRequest({
      method: 'POST',
      url,
      body,
      headers,
      json: true,
      timeout: 60000,
    });
  } catch (error) {
    const details = error?.response?.body || error?.message || error;
    throw new Error('GHL conversations search failed: ' + (typeof details === 'string' ? details : JSON.stringify(details)));
  }
}

const response = await requestJson(requestUrl, requestBody);
const conversations = Array.isArray(response?.conversations) ? response.conversations : [];
const now = new Date().toISOString();

const rows = conversations.filter(function(c) {
  return c && c.type === 'TYPE_CALL';
}).map(function(c) {
  const msg = c.message || {};
  const meta = c.meta || {};
  return {
    json: {
      report_date: (c.dateAdded || now).slice(0, 10),
      source_system: sourceSystem,
      source_key: String(c.id || ''),
      call_id: c.id || '',
      contact_id: c.contactId || '',
      assigned_user_id: c.userId || c.assignedTo || '',
      location_id: c.locationId || '',
      direction: msg.direction || c.direction || 'unknown',
      status: msg.status || c.status || 'completed',
      duration_ms: Number(msg.duration || meta.duration || 0),
      started_at: c.dateAdded || null,
      ended_at: msg.endedAt || null,
      answered_at: msg.answeredAt || null,
      recording_url: msg.recordingUrl || '',
      notes: msg.notes || '',
      payload_json: c,
      dimensions_json: {
        contact_id: c.contactId,
        assigned_user_id: c.assignedTo,
        direction: msg.direction,
        status: msg.status
      },
      metrics_json: { duration_ms: Number(msg.duration || 0) },
      batch_id: batchId,
      loaded_at: now
    }
  };
});

return rows.length > 0 ? rows : [{ json: { ok: true, skipped: true, reason: 'no_calls_in_window', batchId, workflowName } }];
